"""Re-score every scheme in schemes.json from its explicit draw alone.

    python3 verify.py [schemes.json]

Checks, for every scheme:
  * each block seats every bowler exactly once (M pairs of K);
  * the score recomputed from the draw equals the stored score;
  * for rule schemes, the draw equals the one generated by the rule;
  * the stored lower bounds are not beaten (a sanity check on the bounds).
Bowlers in schemes.json are numbered 1..M*K and pairs 1..M (block lists are
in pair order, each pair in bowling order).  Exit status 1 on any mismatch.
"""
from __future__ import annotations

import json
import os
import sys

from model import SCORE_FIELDS, evaluate, rule_draw

HERE = os.path.dirname(os.path.abspath(__file__))


def main():
    path = sys.argv[1] if len(sys.argv) > 1 else os.path.join(HERE, "schemes.json")
    data = json.load(open(path))
    bad = 0
    for s in data["schemes"]:
        draw = [[[x - 1 for x in pr] for pr in blk] for blk in s["draw"]]
        M, K, B = s["M"], s["K"], s["B"]
        ok = len(draw) == B and all(len(blk) == M and all(len(pr) == K for pr in blk) for blk in draw)
        try:
            r = evaluate(draw)
        except AssertionError:
            ok = False
            r = None
        if r is not None:
            sc = [r["score"][i] for i in range(len(SCORE_FIELDS))]
            stored = [s["score"][f] for f in SCORE_FIELDS]
            if sc != stored:
                ok = False
            if any(v < lb for v, lb in zip(sc, s["lower_bound"])):
                ok = False
        if s.get("rule"):
            rd = rule_draw(M, K, B, s["rule"]["d"], s["rule"]["pi"])
            if rd != draw:
                ok = False
        if not ok:
            bad += 1
            print("MISMATCH", s["id"])
    print(f"{len(data['schemes'])} schemes checked, {bad} mismatches")
    sys.exit(1 if bad else 0)


if __name__ == "__main__":
    main()
